(* [comment removed for export] *)
Lemma bcmp_branch : forall ls rs, length ls = length rs ->
  bv_eqb (wz (memcmp_model (zbytes ls) (zbytes rs))) (Z_to_bv 64 0) = lzeqb (zbytes ls) (zbytes rs).
Proof.
  intros ls rs L. rewrite bv_eqb_Z. change (bv_unsigned (Z_to_bv 64 0)) with 0.
  destruct (lzeqb (zbytes ls) (zbytes rs)) eqn:E.
  - apply Z.eqb_eq. apply (proj2 (memcmp_word_zero ls rs L)). apply lzeqb_eq in E.
    revert rs L E. induction ls as [|a ls IH]; intros [|c rs] L E; cbn in *; try reflexivity; try discriminate.
    injection E as E1 E2. f_equal; [apply bv_eq; exact E1 | apply IH; [lia | exact E2]].
  - apply Z.eqb_neq. intros C. apply (proj1 (memcmp_word_zero ls rs L)) in C. subst rs.
    rewrite (proj2 (lzeqb_eq _ _) eq_refl) in E. discriminate.
Qed.

Lemma zbytes_cons : forall b bs, zbytes (b :: bs) = zb b :: zbytes bs. Proof. reflexivity. Qed.

Lemma bytes_at_tail : forall m P b l, bytes_at rsegs m P (b :: l) -> bytes_at rsegs m (P + 1) l.
Proof. intros m P b l H. change (b :: l) with ([b] ++ l) in H. apply bytes_at_app in H. destruct H as [_ H]. exact H. Qed.

Lemma length_2 : forall {X} (l : list X), length l = 2%nat -> exists x y, l = [x; y].
Proof. intros X [|x [|y [|z l]]] H; cbn in H; try lia. exists x, y. reflexivity. Qed.
Lemma length_4 : forall {X} (l : list X), length l = 4%nat -> exists x y z w, l = [x; y; z; w].
Proof. intros X [|x [|y [|z [|w [|v l]]]]] H; cbn in H; try lia. exists x, y, z, w. reflexivity. Qed.
Lemma length_1 : forall {X} (l : list X), length l = 1%nat -> exists x, l = [x].
Proof. intros X [|x [|y l]] H; cbn in H; try lia. exists x. reflexivity. Qed.
Lemma length_pos_cons : forall {X} (l : list X), (1 <= length l)%nat -> exists x l', l = x :: l'.
Proof. intros X [|x l] H; cbn in H; [lia|]. exists x, l. reflexivity. Qed.

(* [comment removed for export] *)
Definition litb (L : list Z) : list byte := map b8 L.
Lemma length_litb : forall L, length (litb L) = length L. Proof. intros. apply length_map. Qed.

