Section HCW.
  Context {HCEIL : HeapCeil}.

(* [comment removed for export] *)
Definition verb_ctx (m m1 : mem) (sp s0v rav : word) (P : Z) (bs : list byte) (p' n' lo : Z) : Prop :=
  rw_cells rsegs m1 (bv_unsigned sp + -32) [C8 (wz p'); C8 (wz n'); C8 s0v; C8 rav]
  /\ bytes_at rsegs m1 P bs
  /\ stk rsegs m1 lo (bv_unsigned sp + -32)
  /\ munch [(lo, bv_unsigned sp)]%Z m m1 /\ wmono rsegs m m1 /\ mem_inv rsegs m1.

Definition verb_pure (sp : word) (P : Z) (bs : list byte) (lo : Z) : Prop :=
  P + Z.of_nat (length bs) < 2^64 /\ lo + 48 <= bv_unsigned sp /\ 0xb4000 <= lo
  /\ (bv_unsigned sp <= P \/ P + Z.of_nat (length bs) <= lo).

End HCW.

(* [comment removed for export] *)
Ltac open_verb CTX PURE :=
  lazymatch type of CTX with verb_ctx _ _ ?sp _ _ _ _ _ _ _ =>
  destruct CTX as (FR & WIN & ST & MU & WM & MI);
  destruct PURE as (P64 & LO & L94 & SEPW);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR
  end.

Ltac verb_rebuild_ctx m sp P :=
  try match goal with C : verb_ctx _ _ _ _ _ _ _ _ _ _ |- _ => clear C end;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
  lazymatch goal with
  | FR : rw_cells _ mx (bv_unsigned sp + -32) [C8 (_ ?p'); C8 (_ ?n'); C8 ?s0v; C8 ?rav], WIN : bytes_at _ mx P ?bs,
    ST : stk _ mx ?lo _, MU : munch _ m mx, WM : wmono _ m mx, MI : mem_inv _ mx |- _ =>
      let CTX := fresh "CTX" in
      assert (CTX : verb_ctx m mx sp s0v rav P bs p' n' lo)
        by (split; [exact FR | split; [exact WIN | split; [exact ST | split; [exact MU | split; [exact WM | exact MI]]]]])
  end end.

(* [comment removed for export] *)
Ltac vwin_load WIN q :=
  lazymatch type of WIN with bytes_at _ ?mx ?it0 ?bs =>
    let b := fresh "b" in let N := fresh "N" in let RD := fresh "RD" in let BR := fresh "BR" in
    destruct (win_byte _ _ _ q WIN ltac:(lia)) as [b N];
    pose proof (zb_range b) as BR; unfold zb in BR;
    pose proof (u8ro_read rsegs _ it0 bs (q - it0) b (Z_to_bv 64 q) WIN N ltac:(lia) ltac:(symmetry; apply wa_of_Z_to_bv; lia)) as RD;
    step; clear RD; change (zxb b) with (Z_to_bv 64 (zb b)); fold (zb b) in BR
  end.

Section HCW2.
  Context {HCEIL : HeapCeil}.

(* [comment removed for export] *)
Lemma lit_EARCH : forall m, mem_inv rsegs m -> bytes_at rsegs m A_EARCH (litb L_EARCH) /\ zbytes (litb L_EARCH) = L_EARCH.
Proof.
  intros m MI. split; [| vm_compute; reflexivity]. unfold A_EARCH.
  apply (ro_cells_bytes_at rsegs m _ [CB (length L_EARCH) (litb L_EARCH)]).
